/**
 * RFC 7807 Problem Details for HTTP APIs
 * 
 * This module provides types and utilities for RFC 7807 compliant error responses.
 * See https://datatracker.ietf.org/doc/html/rfc7807
 */

export interface ProblemDetails {
  /** A URI reference that identifies the problem type */
  type: string;
  /** A short, human-readable summary of the problem type */
  title: string;
  /** The HTTP status code generated by the origin server */
  status: number;
  /** A machine-readable error code */
  code: string;
  /** A human-readable explanation specific to this occurrence */
  detail?: string;
  /** A URI reference that identifies the specific occurrence of the problem */
  instance?: string;
  /** Optional field-level validation errors */
  errors?: ValidationErrorDetail[];
  /** Legacy field for backward compatibility - will be removed in next release */
  error?: string;
}

export interface ValidationErrorDetail {
  field: string;
  message: string;
  code: string;
}

export interface ErrorCatalogEntry {
  code: string;
  title: string;
  status: number;
  description: string;
  type: string;
}

export const ERROR_TYPE_BASE_URI = 'https://callora-backend.vercel.app/errors/';

export function buildTypeUri(code: string): string {
  return `${ERROR_TYPE_BASE_URI}${code.toLowerCase()}`;
}

export function getDefaultTitle(status: number): string {
  const titles: Record<number, string> = {
    400: 'Bad Request',
    401: 'Unauthorized',
    402: 'Payment Required',
    403: 'Forbidden',
    404: 'Not Found',
    408: 'Request Timeout',
    409: 'Conflict',
    413: 'Payload Too Large',
    415: 'Unsupported Media Type',
    422: 'Unprocessable Entity',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    502: 'Bad Gateway',
    503: 'Service Unavailable',
    504: 'Gateway Timeout',
  };
  return titles[status] ?? 'Error';
}

